getPSUIAction.scriptCode:
const vditor = view.ctx.parent.vditor;
const templateView = view.getController('templateshow_view');
if (templateView) {
    const form = templateView.getController('form');
    const [data] = form.getData();
    const description = data.description;
    // 先清空
    vditor.vditor.setValue('');
    vditor.vditor.insertValue(description);
    view.closeView();
}

